            //
            aOrbiterD = ((aOrbiterD + aOrbiterG) + 0x13C3748B327632CCULL) + aTwistOrbiterUpdateSaltC[((aIndex + 15U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x7718F8BCF1F87CA1ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x58F89AE10E0DF171ULL), 27U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x9F504992D37EB2A2ULL;
