            aOrbiterI = (aWandererK + RotL64(aPrevious, 29U)) + 0x3DEF7E9107CD46BFULL;
            aOrbiterK = (aWandererA + RotL64(aCross, 43U)) + 0xC070237DFBE17894ULL;
            aOrbiterA = ((aWandererE + RotL64(aIngress, 48U)) + 0x573CB02823950B96ULL) + aTwistOrbiterAssignSaltE[((aIndex + 3U)) & S_SALT1];
