            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x8449AD8167D34C60ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterK) ^ 0xD17CC3A70E1CE0AFULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x1E0F809B9C421631ULL), 19U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterF) + 0xE3A0665B6AF79F21ULL) + aTwistOrbiterUpdateSaltD[((aIndex + 5U)) & S_SALT1];
