            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0xBE84E98D5A7A0892ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterF) ^ 0x09A6A740BBDAAAA1ULL;
