            aOrbiterD = ((aWandererI + RotL64(aIngress, 47U)) + RotL64(aCarry, 11U)) + 0xDA47ED5B7E93BE6EULL;
            aOrbiterJ = (aWandererK + RotL64(aPrevious, 53U)) + 0xB8A197DF808160F6ULL;
            aOrbiterB = (aWandererF + RotL64(aScatter, 5U)) + 0xDFDCF14D8476EF60ULL;
            //
            aOrbiterK = (aOrbiterK + aOrbiterI) + 0xE48E15557BFA6428ULL;
