            aOrbiterH = (aOrbiterH + aOrbiterG) + 0xA5D6BD06B168A0B9ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterH) ^ 0x8A302150550F2272ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 24U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xC17EC1BD1D9F59E5ULL), 51U);
