            aWandererK = aWandererK + ((RotL64(aCross, 51U) + aOrbiterD) + RotL64(aOrbiterJ, 30U));
            aWandererE = aWandererE ^ ((RotL64(aIngress, 5U) + aOrbiterG) + RotL64(aOrbiterF, 3U));
