            aCross ^= (RotL64(aLightningLaneD[((S_BLOCK1 - aIndex + 13753U)) & S_BLOCK1], 54U) ^ RotL64(aEarthLaneB[((S_BLOCK1 - aIndex + 10372U)) & S_BLOCK1], 11U));
