            aOrbiterJ = ((aWandererA + RotL64(aCross, 60U)) + RotL64(aCarry, 53U)) + 0x276EFE1B91D90C5AULL;
            aOrbiterG = ((aWandererK + RotL64(aScatter, 39U)) + RotL64(aCarry, 11U)) + 0xA9B5164D278D599FULL;
