            aWandererK = aWandererK + ((((RotL64(aScatter, 6U) + aOrbiterA) + RotL64(aOrbiterG, 60U)) + RotL64(aCarry, 5U)) + aKeyRotateAWandererUpdateSaltD[(((31U - aIndex) + 9U)) & S_SALT1]);
