            aOrbiterF = ((aOrbiterF + aOrbiterI) + 0x4DE33E51E957B76FULL) + aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x35BCE96251E50372ULL;
