            aWandererF = aWandererF ^ ((RotL64(aPrevious, 5U) + RotL64(aOrbiterE, 23U)) + aOrbiterJ);
            aWandererA = aWandererA + ((RotL64(aScatter, 53U) + aOrbiterC) + RotL64(aOrbiterE, 41U));
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 21U) + RotL64(aOrbiterG, 3U)) + aOrbiterD);
            aWandererC = aWandererC + ((RotL64(aCross, 43U) + RotL64(aOrbiterA, 47U)) + aOrbiterK);
            aWandererI = aWandererI ^ ((RotL64(aIngress, 41U) + aOrbiterF) + RotL64(aOrbiterH, 39U));
            aWandererE = aWandererE + ((RotL64(aScatter, 27U) + RotL64(aOrbiterE, 10U)) + aOrbiterF);
            aWandererD = aWandererD ^ (((RotL64(aPrevious, 14U) + aOrbiterH) + RotL64(aOrbiterB, 37U)) + aKeyRotateAWandererUpdateSaltC[(((31U - aIndex) + 9U)) & S_SALT1]);
            aWandererB = aWandererB + ((((RotL64(aIngress, 35U) + RotL64(aOrbiterI, 51U)) + aOrbiterK) + RotL64(aCarry, 21U)) + aKeyRotateAWandererUpdateSaltD[((aIndex + 10U)) & S_SALT1]);
            //
            aCarry = aCarry + (RotL64(aWandererD, 44U) ^ aWandererB);
            aCarry = aCarry + (RotL64(aWandererA, 5U) ^ aWandererH);
