            //
            aScatter = (RotL64(aCross, 3U) + RotL64(aIngress, 19U)) ^ (RotL64(aCarry, 37U) + RotL64(aPrevious, 52U));
            aScatter = TwistMix64::DiffuseA((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterE = (aWandererG + RotL64(aIngress, 51U)) + 0x98A1908BFA59BC7DULL;
            aOrbiterB = (((aWandererK + RotL64(aScatter, 5U)) + RotL64(aCarry, 3U)) + 0xAB4FCB4B168864DDULL) + aKeyRotateAOrbiterAssignSaltB[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterK = (((aWandererF + RotL64(aCross, 57U)) + RotL64(aCarry, 47U)) + 0x50E9685F20742AABULL) + aKeyRotateAOrbiterAssignSaltC[((aIndex + 28U)) & S_SALT1];
            aOrbiterH = ((aWandererH + RotL64(aPrevious, 34U)) + RotL64(aCarry, 19U)) + 0x49F9EB731BAD438EULL;
            aOrbiterA = (aWandererB + RotL64(aIngress, 11U)) + 0x0C3B7F67BE7DB311ULL;
            aOrbiterC = (aWandererC + RotL64(aCross, 19U)) + 0x72320BBCC7C23AF6ULL;
