            //
            aOrbiterK = (aOrbiterK + aOrbiterD) + 0x1FDE50919CDD82C1ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterK) ^ 0x92047C9FC0F9BAE1ULL) ^ aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x47BD8C2F684592A9ULL), 37U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterE) + 0x35BE33E5047B75C8ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterD) ^ 0x3BB9DC1AF3CFB1B8ULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 20U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x78B519945E981E9FULL), 57U);
            //
            aIngress = RotL64(aOrbiterE, 53U) ^ aOrbiterH;
            aIngress = aIngress + (RotL64(aOrbiterD, 41U) ^ aOrbiterA);
            aIngress = aIngress + (RotL64(aOrbiterK, 35U) ^ aOrbiterB);
            aIngress = aIngress + RotL64(aOrbiterC, 23U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererF = aWandererF ^ ((RotL64(aCross, 19U) + RotL64(aOrbiterA, 14U)) + aOrbiterC);
            aWandererI = aWandererI + (((RotL64(aPrevious, 57U) + RotL64(aOrbiterB, 47U)) + aOrbiterA) + RotL64(aCarry, 21U));
