            aCross ^= (RotL64(aIceLaneA[((S_BLOCK1 - aIndex + 10813U)) & S_BLOCK1], 39U) ^ RotL64(aWoodLaneD[((aIndex + 8546U)) & S_BLOCK1], 57U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 5U) + RotL64(aCross, 53U)) + (RotL64(aCarry, 24U) ^ RotL64(aIngress, 41U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterA = (((aWandererC + RotL64(aCross, 29U)) + RotL64(aCarry, 27U)) + 0xAE5AAE337CA5F824ULL) + aKeyRotateAOrbiterAssignSaltF[((aIndex + 14U)) & S_SALT1];
            aOrbiterG = ((aWandererF + RotL64(aPrevious, 51U)) + RotL64(aCarry, 13U)) + 0xCDD18C884BF438CCULL;
            aOrbiterB = (aWandererG + RotL64(aIngress, 43U)) + 0x1B0E4119FD8FE5D6ULL;
            aOrbiterI = (((aWandererK + RotL64(aScatter, 60U)) + RotL64(aCarry, 47U)) + 0x0FDB0FCDC43D64C6ULL) + aKeyRotateAOrbiterAssignSaltA[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterH = (aWandererH + RotL64(aIngress, 23U)) + 0x4BC964209834E4D1ULL;
            aOrbiterE = (aWandererA + RotL64(aScatter, 11U)) + 0xBCE12192E143B989ULL;
            aOrbiterJ = (aWandererB + RotL64(aCross, 37U)) + 0x050D3E5390A56FA5ULL;
            //
            aOrbiterA = ((aOrbiterA + aOrbiterG) + 0x5386AB536B379F82ULL) + aKeyRotateAOrbiterUpdateSaltF[((aIndex + 12U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0x161C2C3F667CD909ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x010A4D6DEDA9F2F1ULL), 35U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterH) + 0xFBD1F2ADD4F0BE62ULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 15U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterI) ^ 0x90FC7D0D55246906ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xE0F66F27422778F5ULL), 11U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterE) + 0xBCEA2E97C324334AULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0x2BEF799C87CA8476ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x34B84A80EB87096BULL), 21U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0xB16DC48C7AF41DB5ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterG) ^ 0x8F93A666504AFE25ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x3EB91BCA1398F9D7ULL), 41U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0xF5A549BF0429687CULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterB) ^ 0xBBC10614BEB957C2ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x32B75CC53D7BA733ULL), 47U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterA) + 0x74F45DEAEF17C915ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterE) ^ 0xBABC86989BD91EDAULL) ^ aKeyRotateAOrbiterUpdateSaltA[((aIndex + 7U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x6B6433E996CCEEF9ULL), 53U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0xBB348DFC31123CCBULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterJ) ^ 0xF38D9C875F6AF051ULL) ^ aKeyRotateAOrbiterUpdateSaltB[((aIndex + 17U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x7B6536DFB254940BULL), 3U);
            //
            aIngress = RotL64(aOrbiterG, 60U) ^ aOrbiterI;
            aIngress = aIngress + (aOrbiterA ^ RotL64(aOrbiterB, 3U));
