            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererB = aWandererB ^ (((RotL64(aIngress, 29U) + aOrbiterB) + RotL64(aOrbiterI, 21U)) + aKeyRotateAWandererUpdateSaltA[(((31U - aIndex) + 8U)) & S_SALT1]);
            aWandererG = aWandererG + ((RotL64(aPrevious, 39U) + aOrbiterE) + RotL64(aOrbiterB, 13U));
            aWandererC = aWandererC ^ ((RotL64(aCross, 13U) + aOrbiterG) + RotL64(aOrbiterJ, 27U));
            aWandererK = aWandererK + (((RotL64(aScatter, 53U) + RotL64(aOrbiterB, 37U)) + aOrbiterJ) + RotL64(aCarry, 51U));
            aWandererA = aWandererA ^ (((RotL64(aIngress, 46U) + RotL64(aOrbiterE, 6U)) + aOrbiterH) + aKeyRotateAWandererUpdateSaltC[((aIndex + 29U)) & S_SALT1]);
