            aCarry = aCarry + (aWandererG ^ RotL64(aWandererA, 3U));
            aCarry = aCarry + (RotL64(aWandererC, 54U) ^ aWandererK);
            aCarry = aCarry + (RotL64(aWandererB, 47U) ^ aWandererH);
